class Solution {
  public int minCost(String source, String target, List<List<String>> rules, int[] costs) {
    int n = source.length(), R = rules.size();
    long INF = Long.MAX_VALUE / 4;
    String[] pattern = new String[R], replacement = new String[R];
    long[] ruleCost = new long[R];
    for (int i = 0; i < R; i++) {
      pattern[i] = rules.get(i).get(0);
      replacement[i] = rules.get(i).get(1);
      long stars = 0;
      for (int j = 0; j < pattern[i].length(); j++) if (pattern[i].charAt(j) == '*') stars++;
      ruleCost[i] = costs[i] + stars;
    }
    long[] dp = new long[n + 1];
    java.util.Arrays.fill(dp, INF);
    dp[0] = 0;
    for (int i = 0; i < n; i++) {
      if (dp[i] >= INF) continue;
      if (source.charAt(i) == target.charAt(i)) dp[i + 1] = Math.min(dp[i + 1], dp[i]);
      for (int r = 0; r < R; r++) {
        int len = pattern[r].length();
        if (i + len > n) continue;
        boolean ok = true;
        for (int j = 0; j < len && ok; j++) {
          char pc = pattern[r].charAt(j);
          if (pc != '*' && pc != source.charAt(i + j)) ok = false;
          else if (replacement[r].charAt(j) != target.charAt(i + j)) ok = false;
        }
        if (ok) dp[i + len] = Math.min(dp[i + len], dp[i] + ruleCost[r]);
      }
    }
    return dp[n] >= INF ? -1 : (int) dp[n];
  }
}
